async function dump(id) {
  const n = await figma.getNodeByIdAsync(id);
  function walk(node, depth) {
    let s = '  '.repeat(depth) + node.type + ' | ' + node.name + ' | id=' + node.id + ' | ' + Math.round(node.width) + 'x' + Math.round(node.height);
    if (node.type === 'TEXT') s += ' | chars="' + node.characters + '" | font=' + JSON.stringify(node.fontName);
    if ('fills' in node && Array.isArray(node.fills) && node.fills.length) s += ' | fills=' + JSON.stringify(node.fills).slice(0,150);
    if ('cornerRadius' in node) s += ' | r=' + node.cornerRadius;
    if ('layoutMode' in node && node.layoutMode) s += ' | auto=' + node.layoutMode + ' pad=' + [node.paddingTop,node.paddingRight,node.paddingBottom,node.paddingLeft].join(',') + ' gap=' + node.itemSpacing;
    if (depth < 4 && 'children' in node) for (const c of node.children) s += '\n' + walk(c, depth+1);
    return s;
  }
  return walk(n, 0);
}
