function T(chars, o = {}) {
  const t = figma.createText();
  t.fontName = { family: 'DM Sans', style: o.style || 'Regular' };
  t.characters = chars;
  t.fontSize = o.size || 16;
  t.fills = [{ type: 'SOLID', color: o.color || C.ink }];
  if (o.lh) t.lineHeight = { unit: 'PIXELS', value: o.lh };
  if (o.ls) t.letterSpacing = { unit: 'PERCENT', value: o.ls };
  if (o.align) t.textAlignHorizontal = o.align;
  return t;
}
function F(name) { const f = figma.createFrame(); f.name = name; f.fills = []; f.clipsContent = false; return f; }
function AL(f, o = {}) {
  f.layoutMode = o.dir || 'VERTICAL';
  f.itemSpacing = o.gap || 0;
  const p = o.pad || [0, 0, 0, 0];
  f.paddingTop = p[0]; f.paddingRight = p[1]; f.paddingBottom = p[2]; f.paddingLeft = p[3];
  f.primaryAxisAlignItems = o.align || 'MIN';
  f.counterAxisAlignItems = o.cross || 'MIN';
  f.primaryAxisSizingMode = 'AUTO'; f.counterAxisSizingMode = 'AUTO';
  return f;
}
